+ const customLobbyLeaderboardInfo = {
+ name: {
+ displayName: "Name",
+ sortPriority: 0,
+ },
+ killcount: {
+ displayName: "Kills",
+ sortPriority: 1,
+ }
+ }
+ onPlayerJoin = (pId) => {
+ if (!api.getPlayerDbValue(pId,"joined")) {
+ ["Helmet", "Chestplate", "Gauntlets", "Leggings", "Boots"].forEach((part,i) => {
+ api.setItemSlot(pId,46+i, `Diamond ${part}`, 1, { customAttributes: { enchantments: { "Protection": 3, "Health Regen": 2 },enchantmentTier:"Tier 5"} });
+ })
+ api.giveItem(pId, "Diamond Sword", 1, { customAttributes: { enchantments: { "Attack Speed": 3, "Damage": 2 },enchantmentTier:"Tier 5"} });
+ }
+ api.setPlayerDbValue(pId,"joined", "joined");
+ api.setClientOption(pId, "lobbyLeaderboardInfo", customLobbyLeaderboardInfo);
+ onPlayerKilledOtherPlayer(pId,pId,0,"Air");
+ }
+ onPlayerKilledOtherPlayer = (attacker, damager, damage, item) => {
+ const killcounts = (api.getPlayerDbValue(attacker, "killcounts") ?? 0) + (attacker == damager ? 0 : 1);
+ api.setPlayerDbValue(attacker, "killcounts",killcounts);
+ api.setTargetedPlayerSettingForEveryone(attacker, "lobbyLeaderboardValues", { killcount: killcounts });
+ }
+ }}

